export function cardOf(listing: Listing): ListingCard {
  return Object.assign(new ListingCard(), { id: listing.id, title: listing.title, neighbourhoodName: listing.neighbourhoodName, city: listing.city, kind: listing.kind, price: listing.price, bedrooms: listing.bedrooms, bathrooms: listing.bathrooms, areaSqm: listing.areaSqm, status: listing.status });
}

/**
 * Standalone version of pageOf for use outside NestJS DI context
 * (e.g. queue workers, agent tools). Takes the handles of what it reaches last.
 */
export async function pageOf(listing: Listing, em: EntityManager): Promise<ListingPage> {
  const changes: PriceChange[] = await (em.getRepository(PriceChange).getEntityManager() as SqlEntityManager).createQueryBuilder(PriceChange, 'e_price_change').select('*').where('e_price_change.listing_id = ?', [listing.id]).orderBy({ 'e_price_change.created_at': 'DESC' }).limit(20).getResultList();
  return Object.assign(new ListingPage(), { home: await cardOf(listing), summary: listing.summary, agentName: listing.agentName, point: Object.assign(new GeoPoint(), { latitude: listing.latitude, longitude: listing.longitude }), priceHistory: changes.map((c) => Object.assign(new PriceStep(), { oldPrice: c.oldPrice, newPrice: c.newPrice, at: c.createdAt })) });
}

/**
 * Standalone version of ownListing for use outside NestJS DI context
 * (e.g. queue workers, agent tools). Takes the handles of what it reaches last.
 */
export async function ownListing(id: string, em: EntityManager): Promise<Listing> {
  const listing = await em.getRepository(Listing).findOne({ id: id });
  if (!listing) {
    throw new NotFoundException("Not found");
  }
  if ((String(listing.agentEmail) !== String((currentUserIdentity().email as string)))) {
    throw new NotYourListingError({});
  }
  return listing;
}

